create extension if not exists pgcrypto;
create table if not exists projects(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,description text default '',category text default '',location text default '',cover_image text default '',published boolean default true,created_at timestamptz default now());
create table if not exists project_images(id uuid primary key default gen_random_uuid(),project_id uuid references projects(id) on delete cascade,image_url text not null,sort_order int default 0,created_at timestamptz default now());
create table if not exists services(id uuid primary key default gen_random_uuid(),title text not null,description text default '',image_url text default '',sort_order int default 0,published boolean default true,created_at timestamptz default now());
create table if not exists enquiries(id uuid primary key default gen_random_uuid(),name text not null,phone text not null,email text default '',project_type text default '',property_type text default '',budget text default '',city text default '',message text default '',status text default 'NEW',created_at timestamptz default now());
create table if not exists contact_settings(id int primary key default 1,phone text default '',whatsapp text default '',email text default '',address text default '',facebook text default '',instagram text default '',google_maps text default '',whatsapp_message text default '');
create table if not exists site_settings(key text primary key,value jsonb not null);
insert into contact_settings(id) values(1) on conflict(id) do nothing;
insert into storage.buckets(id,name,public) values('project-images','project-images',true) on conflict(id) do nothing;
alter table projects enable row level security;alter table project_images enable row level security;alter table services enable row level security;alter table enquiries enable row level security;alter table contact_settings enable row level security;alter table site_settings enable row level security;
create policy "public read projects" on projects for select using (published=true);create policy "auth manage projects" on projects for all to authenticated using (true) with check (true);
create policy "public read project images" on project_images for select using (true);create policy "auth manage project images" on project_images for all to authenticated using (true) with check (true);
create policy "public read services" on services for select using (published=true);create policy "auth manage services" on services for all to authenticated using (true) with check (true);
create policy "public read contact" on contact_settings for select using (true);create policy "auth manage contact" on contact_settings for all to authenticated using (true) with check (true);
create policy "public read site settings" on site_settings for select using (true);create policy "auth manage site settings" on site_settings for all to authenticated using (true) with check (true);
create policy "public insert enquiries" on enquiries for insert with check (true);create policy "auth read enquiries" on enquiries for select to authenticated using (true);create policy "auth update enquiries" on enquiries for update to authenticated using (true) with check (true);
create policy "public read project images bucket" on storage.objects for select using (bucket_id='project-images');create policy "auth upload project images" on storage.objects for insert to authenticated with check (bucket_id='project-images');create policy "auth delete project images" on storage.objects for delete to authenticated using (bucket_id='project-images');
